#!/bin/sh
# @TITLE@ on the Miyoo Mini family: App/@FOLDER@/launch.sh. Every launcher in this release (the
# OS's Apps entry, Onion's Games entry, MinUI's .pak) ends up here, so the game always starts the
# same way. What it writes stays in this folder (logs in ./data); your ROM can sit here as rom.z64.
# Generated by miyoo/tools/miyoo_pack.py from miyoo/templates/launch.sh.
# A launcher may set @ENV@_ROTATE=0 first (MinUI's SDL turns the panel itself).
DIR=$(cd "$(dirname "$0")" && pwd)
cd "$DIR" || exit 1
mkdir -p data
echo "$(date) $0 $* (LD_PRELOAD=$LD_PRELOAD)" > data/launch.log
export @ENV@_DATA="@DATADIR@" # game.json "data": where the game keeps what it writes
export HOME="$DIR"
# Sound: the Mini's SDL 1.2 only has OSS (/dev/dsp), which exists through the OS's audioserver and
# libpadsp.so. Onion preloads it for Apps but not for everything; set it here either way (the
# GoldenEye port on the user's Mini Plus, 2026-10-01: no sound without it).
# Only while an audioserver runs (Onion, stock, MinUI on the Plus, Allium, spruce): libpadsp.so pipes
# to it; without one, the SDL's own MI_AO/dsp driver is the way.
unset LD_PRELOAD
if pgrep audioserver > /dev/null 2>&1; then
    for PADSP in /mnt/SDCARD/miyoo/lib/libpadsp.so /customer/lib/libpadsp.so; do
        if [ -f "$PADSP" ]; then export LD_PRELOAD="$PADSP"; break; fi
    done
fi
export SDL_AUDIODRIVER=dsp # OSS read/write (the shim does not do the DMA driver's mmap)
export LD_LIBRARY_PATH="$DIR/lib:$LD_LIBRARY_PATH"
# Both cores at full clock while the game runs (the renderer is CPU-bound; the OS sets its own
# governor back when it takes over again).
{ echo performance > /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor; } 2>/dev/null
# The second core (miyoo_worker: the renderer splits each frame's drawing across both): online if an
# OS left it off.
CPU1=/sys/devices/system/cpu/cpu1/online
[ -f "$CPU1" ] && [ "$(cat "$CPU1" 2>/dev/null)" = 0 ] && { echo 1 > "$CPU1"; } 2>/dev/null
echo "cores online: $(cat /sys/devices/system/cpu/online 2>/dev/null)" >> data/launch.log
echo "LD_PRELOAD=$LD_PRELOAD @ENV@_ROTATE=$@ENV@_ROTATE" >> data/launch.log
# Onion on a Mini v4 / Mini Flip (752x560 panel) leaves /tmp/new_res_available and sets the screen to 752x560
# for this game (App/@FOLDER@/full_resolution, FullResolution=1 in the Ports shortcut). If the screen is still
# 640x480 here, the game opens that and shows small: logged, not changed (the game takes the screen as it is).
if [ -f /tmp/new_res_available ]; then
    FB0=$(cat /sys/class/graphics/fb0/virtual_size 2>/dev/null)
    echo "752x560 panel (Onion /tmp/new_res_available); fb0 at start: ${FB0:-unknown}" >> data/launch.log
    case "$FB0" in 640,*) echo "WARNING: the screen is 640x480 on a 752x560 panel: the game will not fill it" >> data/launch.log ;; esac
fi
chmod +x ./@EXE@ 2>/dev/null
# exec: the OS's SIGTERM / SIGSTOP must reach the game itself (Allium signals only the process it
# started; spruce kills it outright, so the game saves often anyway).
exec ./@EXE@
